import paletteJson from "@shared/palette.json";
// Type-only import: keeps culori (used by the generator) out of the web bundle.
import type { Palette, PaletteCell } from "@tint/game-core";
import { BOARD_COLS, BOARD_ROWS, type Cell } from "@tint/protocol";

/** The 24 × 12 board, generated by `pnpm palette` — the single source of truth for every client. */
export const palette = paletteJson as Palette;

if (palette.cols !== BOARD_COLS || palette.rows !== BOARD_ROWS) {
  throw new Error(
    `palette.json is ${palette.cols}×${palette.rows}, expected ${BOARD_COLS}×${BOARD_ROWS}`,
  );
}

export function cellAt(x: number, y: number): PaletteCell {
  const cell = palette.cells[y * BOARD_COLS + x];
  if (!cell) throw new RangeError(`no cell at (${x}, ${y})`);
  return cell;
}

export const hexAt = (x: number, y: number): string => cellAt(x, y).hex;
export const hexOf = (c: Cell): string => hexAt(c.x, c.y);

/** Rows y0..y1 (inclusive) as hex strings, row-major — used for the decorative strip on setup. */
export function rows(y0: number, y1: number): string[][] {
  const out: string[][] = [];
  for (let y = y0; y <= y1; y++) {
    out.push(Array.from({ length: BOARD_COLS }, (_, x) => hexAt(x, y)));
  }
  return out;
}
